    /// <summary>buffer size is invalid</summary>
    InvalidSize = 2,
    /// <summary>buffer offset is invalid</summary>
    InvalidOffset = 3,
    /// <summary>surface was destroyed before its role object</summary>
    DefunctRoleObject = 4,
    /// <summary>no buffer was attached</summary>
    NoBuffer = 5,
}

/// <summary>Group of input devices</summary>
/// <remarks>
/// A seat is a group of keyboards, pointer and touch devices. This
/// object is published as a global during start up, or when such a
/// device is hot plugged.  A seat typically has a pointer and
/// maintains a keyboard focus and a pointer focus.
/// </remarks>
public sealed unsafe partial class WlSeat : WlProxy, IWaylandProxy<WlSeat>
{
    public static string InterfaceName => "wl_seat";
    public static uint MaxVersion => 11;
    public static WlInterface* NativeInterface => WaylandInterfaces.wl_seat;
    public static WlSeat Wrap(nint handle) => new(handle);

    private WlSeat(nint handle) : base(handle) { }

    /// <summary>Return pointer object</summary>
    /// <remarks>
    /// The ID provided will be initialized to the wl_pointer interface
    /// for this seat.
    /// <para/>
    /// This request only takes effect if the seat has the pointer
    /// capability, or has had the pointer capability in the past.
    /// It is a protocol violation to issue this request on a seat that has
    /// never had the pointer capability. The missing_capability error will
    /// be sent in this case.
    /// </remarks>
    public WlPointer GetPointer()
    {
        WlArgument* args = stackalloc WlArgument[1];
        args[0].o = 0;
        return WlPointer.Wrap(MarshalNew(0, args, WlPointer.NativeInterface, BoundVersion, 1, "get_pointer"));
    }

    /// <summary>Return keyboard object</summary>
    /// <remarks>
    /// The ID provided will be initialized to the wl_keyboard interface
    /// for this seat.
    /// <para/>
    /// This request only takes effect if the seat has the keyboard
    /// capability, or has had the keyboard capability in the past.
    /// It is a protocol violation to issue this request on a seat that has
    /// never had the keyboard capability. The missing_capability error will
    /// be sent in this case.
    /// </remarks>
    public WlKeyboard GetKeyboard()
    {
        WlArgument* args = stackalloc WlArgument[1];
        args[0].o = 0;
        return WlKeyboard.Wrap(MarshalNew(1, args, WlKeyboard.NativeInterface, BoundVersion, 1, "get_keyboard"));
    }

    /// <summary>Return touch object</summary>
    /// <remarks>
    /// The ID provided will be initialized to the wl_touch interface
    /// for this seat.
    /// <para/>
    /// This request only takes effect if the seat has the touch
    /// capability, or has had the touch capability in the past.
    /// It is a protocol violation to issue this request on a seat that has
    /// never had the touch capability. The missing_capability error will
    /// be sent in this case.
    /// </remarks>
    public WlTouch GetTouch()
    {
        WlArgument* args = stackalloc WlArgument[1];
        args[0].o = 0;
        return WlTouch.Wrap(MarshalNew(2, args, WlTouch.NativeInterface, BoundVersion, 1, "get_touch"));
    }

    /// <summary>Sends <c>release</c> (when bound at version 5 or later), then destroys the proxy.</summary>
    protected override void Destroy()
    {
        if (BoundVersion < 5)
            base.Destroy();
        else
            Marshal(3, null, 5, "release", destroy: true);
    }

    /// <summary>Seat capabilities changed</summary>
    /// <remarks>
    /// This is sent on binding to the seat global or whenever a seat gains
    /// or loses the pointer, keyboard or touch capabilities.
    /// The argument is a capability enum containing the complete set of
    /// capabilities this seat has.
    /// <para/>
    /// When the pointer capability is added, a client may create a
    /// wl_pointer object using the wl_seat.get_pointer request. This object
    /// will receive pointer events until the capability is removed in the
    /// future.
    /// <para/>
    /// When the pointer capability is removed, a client should destroy the
    /// wl_pointer objects associated with the seat where the capability was
    /// removed, using the wl_pointer.release request. No further pointer
    /// events will be received on these objects.
    /// <para/>
    /// In some compositors, if a seat regains the pointer capability and a
    /// client has a previously obtained wl_pointer object of version 4 or
    /// less, that object may start sending pointer events again. This
    /// behavior is considered a misinterpretation of the intended behavior
    /// and must not be relied upon by the client. wl_pointer objects of
    /// version 5 or later must not send events if created before the most
    /// recent event notifying the client of an added pointer capability.
    /// <para/>
    /// The above behavior also applies to wl_keyboard and wl_touch with the
    /// keyboard and touch capabilities, respectively.
    /// </remarks>
    public event Action<WlSeatCapabilitiesEvent>? Capabilities;

    /// <summary>Unique identifier for this seat</summary>
    /// <remarks>
    /// In a multi-seat configuration the seat name can be used by clients to
    /// help identify which physical devices the seat represents.
    /// <para/>
    /// The seat name is a UTF-8 string with no convention defined for its
    /// contents. Each name is unique among all wl_seat globals. The name is
    /// only guaranteed to be unique for the current compositor instance.
    /// <para/>
    /// The same seat names are used for all clients. Thus, the name can be
    /// shared across processes to refer to a specific wl_seat global.
    /// <para/>
    /// The name event is sent after binding to the seat global, and should be sent
    /// before announcing capabilities. This event is only sent once per seat object,
    /// and the name does not change over the lifetime of the wl_seat global.
    /// <para/>
    /// Compositors may re-use the same seat name if the wl_seat global is
    /// destroyed and re-created later.
    /// <para>Since version 2.</para>
    /// </remarks>
    public event Action<WlSeatNameEvent>? Name;

    protected override void Dispatch(uint opcode, WlArgument* args)
    {
        switch (opcode)
        {
            case 0:
                Capabilities?.Invoke(new WlSeatCapabilitiesEvent(args));
                break;
            case 1:
                Name?.Invoke(new WlSeatNameEvent(args));
                break;
        }
    }
}

/// <summary>Arguments of <see cref="WlSeat"/>'s <c>capabilities</c> event. Only valid during the event handler.</summary>
