{
    readonly WlArgument* args;

    internal WlSeatCapabilitiesEvent(WlArgument* args) => this.args = args;

    /// <summary>capabilities of the seat</summary>
    public WlSeatCapability Capabilities => (WlSeatCapability)args[0].u;
}

