    protected override void Dispatch(uint opcode, WlArgument* args)
    {
        switch (opcode)
        {
            case 0:
                Keymap?.Invoke(new WlKeyboardKeymapEvent(args));
                CloseFd(args[1].h);
                break;
            case 1:
                Enter?.Invoke(new WlKeyboardEnterEvent(args));
                break;
            case 2:
                Leave?.Invoke(new WlKeyboardLeaveEvent(args));
                break;
            case 3:
                Key?.Invoke(new WlKeyboardKeyEvent(args));
                break;
            case 4:
                Modifiers?.Invoke(new WlKeyboardModifiersEvent(args));
                break;
            case 5:
                RepeatInfo?.Invoke(new WlKeyboardRepeatInfoEvent(args));
                break;
        }
    }
}

