    /// <para/>
    /// The name event is sent after binding the output object. This event is
    /// only sent once per output object, and the name does not change over the
    /// lifetime of the wl_output global.
    /// <para/>
    /// Compositors may re-use the same output name if the wl_output global is
    /// destroyed and re-created later. Compositors should avoid re-using the
    /// same name if possible.
    /// <para/>
    /// The name event will be followed by a done event.
    /// <para>Since version 4.</para>
    /// </remarks>
    public event Action<WlOutputNameEvent>? Name;

    /// <summary>Human-readable description of this output</summary>
    /// <remarks>
    /// Many compositors can produce human-readable descriptions of their
    /// outputs. The client may wish to know this description as well, e.g. for
    /// output selection purposes.
    /// <para/>
    /// The description is a UTF-8 string with no convention defined for its
    /// contents. The description is not guaranteed to be unique among all
    /// wl_output globals. Examples might include 'Foocorp 11" Display' or
    /// 'Virtual X11 output via :1'.
    /// <para/>
    /// The description event is sent after binding the output object and
    /// whenever the description changes. The description is optional, and may
    /// not be sent at all.
    /// <para/>
    /// The description event will be followed by a done event.
    /// <para>Since version 4.</para>
    /// </remarks>
    public event Action<WlOutputDescriptionEvent>? Description;

    protected override void Dispatch(uint opcode, WlArgument* args)
    {
        switch (opcode)
        {
            case 0:
                Geometry?.Invoke(new WlOutputGeometryEvent(args));
                break;
            case 1:
                Mode?.Invoke(new WlOutputModeEvent(args));
                break;
            case 2:
                Done?.Invoke();
                break;
            case 3:
                Scale?.Invoke(new WlOutputScaleEvent(args));
                break;
            case 4:
                Name?.Invoke(new WlOutputNameEvent(args));
                break;
            case 5:
                Description?.Invoke(new WlOutputDescriptionEvent(args));
                break;
        }
    }
}

