/// <summary>Sub-surface compositing</summary>
/// <remarks>
/// The global interface exposing sub-surface compositing capabilities.
/// A wl_surface, that has sub-surfaces associated, is called the
/// parent surface. Sub-surfaces can be arbitrarily nested and create
/// a tree of sub-surfaces.
/// <para/>
/// The root surface in a tree of sub-surfaces is the main
/// surface. The main surface cannot be a sub-surface, because
/// sub-surfaces must always have a parent.
/// <para/>
/// A main surface with its sub-surfaces forms a (compound) window.
/// For window management purposes, this set of wl_surface objects is
/// to be considered as a single window, and it should also behave as
/// such.
/// <para/>
/// The aim of sub-surfaces is to offload some of the compositing work
/// within a window from clients to the compositor. A prime example is
/// a video player with decorations and video in separate wl_surface
/// objects. This should allow the compositor to pass YUV video buffer
/// processing to dedicated overlay hardware when possible.
/// </remarks>
public sealed unsafe partial class WlSubcompositor : WlProxy, IWaylandProxy<WlSubcompositor>
{
    public static string InterfaceName => "wl_subcompositor";
    public static uint MaxVersion => 1;
    public static WlInterface* NativeInterface => WaylandInterfaces.wl_subcompositor;
    public static WlSubcompositor Wrap(nint handle) => new(handle);

    private WlSubcompositor(nint handle) : base(handle) { }

    /// <summary>Sends <c>destroy</c>, then destroys the proxy.</summary>
    protected override void Destroy()
    {
        Marshal(0, null, 1, "destroy", destroy: true);
    }

    /// <summary>Give a surface the role sub-surface</summary>
    /// <remarks>
    /// Create a sub-surface interface for the given surface, and
    /// associate it with the given parent surface. This turns a
    /// plain wl_surface into a sub-surface.
    /// <para/>
    /// The to-be sub-surface must not already have another role, and it
    /// must not have an existing wl_subsurface object. Otherwise the
    /// bad_surface protocol error is raised.
    /// <para/>
    /// Adding sub-surfaces to a parent is a double-buffered operation on the
    /// parent (see wl_surface.commit). The effect of adding a sub-surface
    /// becomes visible on the next time the state of the parent surface is
    /// applied.
    /// <para/>
    /// The parent surface must not be one of the child surface's descendants,
    /// and the parent must be different from the child surface, otherwise the
    /// bad_parent protocol error is raised.
    /// <para/>
    /// This request modifies the behaviour of wl_surface.commit request on
    /// the sub-surface, see the documentation on wl_subsurface interface.
    /// </remarks>
    /// <param name="surface">the surface to be turned into a sub-surface</param>
    /// <param name="parent">the parent surface</param>
    public WlSubsurface GetSubsurface(WlSurface surface, WlSurface parent)
    {
        WlArgument* args = stackalloc WlArgument[3];
        args[0].o = 0;
        args[1].o = WlProxy.HandleOf(surface);
        args[2].o = WlProxy.HandleOf(parent);
        return WlSubsurface.Wrap(MarshalNew(1, args, WlSubsurface.NativeInterface, BoundVersion, 1, "get_subsurface"));
    }
}

public enum WlSubcompositorError : uint
{
    /// <summary>the to-be sub-surface is invalid</summary>
    BadSurface = 0,
    /// <summary>the to-be sub-surface parent is invalid</summary>
    BadParent = 1,
}

/// <summary>Sub-surface interface to a wl_surface</summary>
/// <remarks>
/// An additional interface to a wl_surface object, which has been
/// made a sub-surface. A sub-surface has one parent surface. A
/// sub-surface's size and position are not limited to that of the parent.
/// Particularly, a sub-surface is not automatically clipped to its
/// parent's area.
/// <para/>
/// A sub-surface becomes mapped, when a non-NULL wl_buffer is applied
/// and the parent surface is mapped. The order of which one happens
/// first is irrelevant. A sub-surface is hidden if the parent becomes
/// hidden, or if a NULL wl_buffer is applied. These rules apply
/// recursively through the tree of surfaces.
/// <para/>
/// A sub-surface can be in one of two modes. The possible modes are
/// synchronized and desynchronized, see methods wl_subsurface.set_sync and
/// wl_subsurface.set_desync.
/// <para/>
/// The main surface can be thought to be always in desynchronized mode,
/// since it does not have a parent in the sub-surfaces sense.
/// <para/>
/// Even if a sub-surface is in desynchronized mode, it will behave as
/// in synchronized mode, if its parent surface behaves as in
/// synchronized mode. This rule is applied recursively throughout the
/// tree of surfaces. This means, that one can set a sub-surface into
/// synchronized mode, and then assume that all its child and grand-child
/// sub-surfaces are synchronized, too, without explicitly setting them.
/// <para/>
/// If a surface behaves as in synchronized mode, it is effectively
/// synchronized, otherwise it is effectively desynchronized.
/// <para/>
/// A sub-surface is initially in the synchronized mode.
/// <para/>
/// The wl_subsurface interface has requests which modify double-buffered
/// state of the parent surface (wl_subsurface.set_position, .place_above and
/// .place_below).
/// <para/>
/// Destroying a sub-surface takes effect immediately. If you need to
/// synchronize the removal of a sub-surface to the parent surface update,
/// unmap the sub-surface first by attaching a NULL wl_buffer, update parent,
/// and then destroy the sub-surface.
/// <para/>
/// If the parent wl_surface object is destroyed, the sub-surface is
/// unmapped.
/// <para/>
/// A sub-surface never has the keyboard focus of any seat.
/// <para/>
/// The wl_surface.offset request is ignored: clients must use set_position
/// instead to move the sub-surface.
/// </remarks>
public sealed unsafe partial class WlSubsurface : WlProxy, IWaylandProxy<WlSubsurface>
{
    public static string InterfaceName => "wl_subsurface";
    public static uint MaxVersion => 1;
    public static WlInterface* NativeInterface => WaylandInterfaces.wl_subsurface;
    public static WlSubsurface Wrap(nint handle) => new(handle);

    private WlSubsurface(nint handle) : base(handle) { }

    /// <summary>Sends <c>destroy</c>, then destroys the proxy.</summary>
    protected override void Destroy()
    {
        Marshal(0, null, 1, "destroy", destroy: true);
    }

    /// <summary>Reposition the sub-surface</summary>
    /// <remarks>
    /// This sets the position of the sub-surface, relative to the parent
    /// surface.
    /// <para/>
    /// The sub-surface will be moved so that its origin (top left
    /// corner pixel) will be at the location x, y of the parent surface
    /// coordinate system. The coordinates are not restricted to the parent
    /// surface area. Negative values are allowed.
    /// <para/>
    /// The initial position is 0, 0.
    /// <para/>
    /// Position is double-buffered state on the parent surface, see
    /// wl_subsurface and wl_surface.commit for more information.
    /// </remarks>
    /// <param name="x">x coordinate in the parent surface</param>
    /// <param name="y">y coordinate in the parent surface</param>
    public void SetPosition(int x, int y)
    {
        WlArgument* args = stackalloc WlArgument[2];
        args[0].i = x;
        args[1].i = y;
        Marshal(1, args, 1, "set_position");
    }

    /// <summary>Restack the sub-surface</summary>
    /// <remarks>
    /// This sub-surface is taken from the stack, and put back just
    /// above the reference surface, changing the z-order of the sub-surfaces.
    /// The reference surface must be one of the sibling surfaces, or the
    /// parent surface. Using any other surface, including this sub-surface,
    /// will cause a protocol error.
    /// <para/>
    /// A new sub-surface is initially added as the top-most in the stack
    /// of its siblings and parent.
    /// <para/>
    /// Z-order is double-buffered state on the parent surface, see
    /// wl_subsurface and wl_surface.commit for more information.
    /// </remarks>
    /// <param name="sibling">the reference surface</param>
    public void PlaceAbove(WlSurface sibling)
    {
        WlArgument* args = stackalloc WlArgument[1];
        args[0].o = WlProxy.HandleOf(sibling);
        Marshal(2, args, 1, "place_above");
    }

    /// <summary>Restack the sub-surface</summary>
    /// <remarks>
    /// The sub-surface is placed just below the reference surface.
    /// <para/>
    /// See wl_subsurface.place_above.
    /// </remarks>
    /// <param name="sibling">the reference surface</param>
    public void PlaceBelow(WlSurface sibling)
    {
        WlArgument* args = stackalloc WlArgument[1];
        args[0].o = WlProxy.HandleOf(sibling);
        Marshal(3, args, 1, "place_below");
    }

    /// <summary>Set sub-surface to synchronized mode</summary>
    /// <remarks>
    /// Change the commit behaviour of the sub-surface to synchronized
    /// mode.
    /// <para/>
    /// See wl_subsurface and wl_surface.commit for more information.
    /// </remarks>
    public void SetSync()
    {
        Marshal(4, null, 1, "set_sync");
    }

    /// <summary>Set sub-surface to desynchronized mode</summary>
    /// <remarks>
    /// Change the commit behaviour of the sub-surface to desynchronized
    /// mode.
    /// <para/>
    /// See wl_subsurface and wl_surface.commit for more information.
    /// </remarks>
    public void SetDesync()
    {
        Marshal(5, null, 1, "set_desync");
    }
}

public enum WlSubsurfaceError : uint
{
    /// <summary>wl_surface is not a sibling or the parent</summary>
    BadSurface = 0,
}

/// <summary>Wayland protocol fixes</summary>
/// <remarks>
/// This global fixes problems with other core-protocol interfaces that
/// cannot be fixed in these interfaces themselves.
/// </remarks>
public sealed unsafe partial class WlFixes : WlProxy, IWaylandProxy<WlFixes>
{
    public static string InterfaceName => "wl_fixes";
    public static uint MaxVersion => 2;
    public static WlInterface* NativeInterface => WaylandInterfaces.wl_fixes;
    public static WlFixes Wrap(nint handle) => new(handle);

    private WlFixes(nint handle) : base(handle) { }

    /// <summary>Sends <c>destroy</c>, then destroys the proxy.</summary>
    protected override void Destroy()
    {
        Marshal(0, null, 1, "destroy", destroy: true);
    }

    /// <summary>Destroy a wl_registry</summary>
    /// <remarks>
    /// This request destroys a wl_registry object.
    /// <para/>
    /// The client should no longer use the wl_registry after making this
    /// request.
    /// <para/>
    /// The compositor will emit a wl_display.delete_id event with the object ID
    /// of the registry and will no longer emit any events on the registry. The
    /// client should re-use the object ID once it receives the
    /// wl_display.delete_id event.
    /// </remarks>
    /// <param name="registry">the registry to destroy</param>
    public void DestroyRegistry(WlRegistry registry)
    {
        WlArgument* args = stackalloc WlArgument[1];
        args[0].o = WlProxy.HandleOf(registry);
        Marshal(1, args, 1, "destroy_registry");
    }

    /// <summary>Acknowledge global removal</summary>
    /// <remarks>
    /// Acknowledge the removal of the specified global.
    /// <para/>
    /// If no global with the specified name exists or the global is not removed,
    /// the wl_fixes.invalid_ack_remove protocol error will be posted.
    /// <para/>
    /// Due to the Wayland protocol being asynchronous, the wl_global objects
    /// cannot be destroyed immediately. For example, if a wl_global is removed
    /// and a client attempts to bind that global around same time, it can
    /// result in a protocol error due to an unknown global name in the bind
    /// request.
    /// <para/>
    /// In order to avoid crashing clients, the compositor should remove the
    /// wl_global once it is guaranteed that no more bind requests will come.
    /// <para/>
    /// The wl_fixes.ack_global_remove() request is used to signal to the
    /// compositor that the client will not bind the given global anymore. After
    /// all clients acknowledge the removal of the global, the compositor can
    /// safely destroy it.
    /// <para/>
    /// The client must call the wl_fixes.ack_global_remove() request in
    /// response to a wl_registry.global_remove() event even if it did not bind
    /// the corresponding global.
    /// <para>Since version 2.</para>
    /// </remarks>
    /// <param name="registry">the registry object</param>
    /// <param name="name">unique name of the global</param>
    public void AckGlobalRemove(WlRegistry registry, uint name)
    {
        WlArgument* args = stackalloc WlArgument[2];
        args[0].o = WlProxy.HandleOf(registry);
        args[1].u = name;
        Marshal(2, args, 2, "ack_global_remove");
    }
}

/// <summary>Wl_fixes error values</summary>
/// <remarks>
/// These errors can be emitted in response to wl_fixes requests.
/// </remarks>
public enum WlFixesError : uint
{
    /// <summary>unknown global or the global is not removed</summary>
    InvalidAckRemove = 0,
}
